package app.officinalibri;

import org.json.*;
import java.io.*;
import java.net.*;
import javax.net.ssl.HttpsURLConnection;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;

/** Google-only transport. OAuth tokens never enter the WebView. */
public final class DriveHttp implements DriveFiles.Transport {
 private static final String API="https://www.googleapis.com/drive/v3/";
 private final String token;
 private java.util.Map<String,String> blobIndex;
 public DriveHttp(String token){this.token=token;}
 private static String enc(String v)throws Exception {return URLEncoder.encode(v,"UTF-8");}
 private static String id(String v)throws IOException {if(!v.matches("[A-Za-z0-9_-]{1,200}"))throw new IOException("Identificativo Drive non valido");return v;}
 public static URL allowed(String address)throws Exception {URI u=new URI(address);if(!"https".equals(u.getScheme())||!"www.googleapis.com".equals(u.getHost())||u.getUserInfo()!=null||u.getFragment()!=null||(u.getPort()!=-1&&u.getPort()!=443)||!(u.getPath().startsWith("/drive/v3/")||u.getPath().startsWith("/upload/drive/v3/")))throw new IOException("Indirizzo Drive non consentito");return u.toURL();}
 private HttpsURLConnection connection(String url,String method)throws Exception {HttpsURLConnection c=(HttpsURLConnection)allowed(url).openConnection();c.setRequestMethod(method);c.setInstanceFollowRedirects(false);c.setConnectTimeout(20000);c.setReadTimeout(60000);c.setRequestProperty("Authorization","Bearer "+token);return c;}
 private static void success(HttpsURLConnection c)throws Exception {int code=c.getResponseCode();if(code==401){c.disconnect();throw new IOException("Accesso Google scaduto: ricollega l’account");}if((code<200||code>=300)&&code!=308){c.disconnect();throw new IOException("Drive non ha completato l’operazione (HTTP "+code+"). Copia locale conservata");}}
 private static byte[] limited(InputStream input,long max)throws Exception {try(InputStream in=input;ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[65536];long size=0;for(int n;(n=in.read(b))!=-1;){size+=n;if(size>max)throw new IOException("Risposta Drive troppo grande");out.write(b,0,n);}return out.toByteArray();}}
 private static JSONObject body(HttpsURLConnection c)throws Exception {return new JSONObject(new String(limited(c.getInputStream(),8L*1024*1024),StandardCharsets.UTF_8));}
 private JSONObject json(String url)throws Exception {HttpsURLConnection c=connection(url,"GET");try{success(c);return body(c);}finally{c.disconnect();}}
 private JSONArray list(String query)throws Exception {JSONArray files=new JSONArray();String page="";do{JSONObject r=json(API+"files?spaces=appDataFolder&pageSize=100&fields="+enc("nextPageToken,files(id,name,size,sha256Checksum,appProperties)")+"&q="+enc("trashed = false and ("+query+")")+(page.isEmpty()?"":"&pageToken="+enc(page)));JSONArray f=r.optJSONArray("files");if(f!=null)for(int i=0;i<f.length();i++)files.put(f.getJSONObject(i));if(files.length()>10000)throw new IOException("Archivio Drive oltre il limite iniziale");page=r.optString("nextPageToken","");}while(!page.isEmpty());return files;}
 @Override public JSONObject account()throws Exception {JSONObject u=json(API+"about?fields="+enc("user(permissionId,displayName,emailAddress)")).getJSONObject("user");return new JSONObject().put("id",u.getString("permissionId")).put("label",u.optString("emailAddress",u.optString("displayName","Google Drive")));}
 public JSONObject version(String version)throws Exception {if(!version.matches("[a-f0-9-]{36}"))throw new IOException("Versione non riconosciuta");JSONArray found=list("appProperties has { key='kind' and value='officina-commit-1' } and appProperties has { key='version' and value='"+version+"' }");if(found.length()!=1)throw new IOException("Versione Drive assente o ambigua");JSONObject meta=found.getJSONObject(0);return DriveFiles.matches(json(API+"files/"+id(meta.getString("id"))+"?alt=media"),DriveFiles.summary(meta.getJSONObject("appProperties")));}
 @Override public JSONArray commits()throws Exception {JSONArray files=list("appProperties has { key='kind' and value='officina-commit-1' }"),summaries=new JSONArray(),result=new JSONArray();if(files.length()>2000)throw new IOException("Cronologia oltre il limite iniziale di 2000 versioni");java.util.Set<String> parents=new java.util.HashSet<>();for(int i=0;i<files.length();i++){JSONObject s=DriveFiles.summary(files.getJSONObject(i).getJSONObject("appProperties"));summaries.put(s);JSONArray pp=s.getJSONArray("parents");for(int j=0;j<pp.length();j++)parents.add(pp.getString(j));}for(int i=0;i<files.length();i++){JSONObject s=summaries.getJSONObject(i);result.put(parents.contains(s.getString("id"))?s:DriveFiles.matches(json(API+"files/"+id(files.getJSONObject(i).getString("id"))+"?alt=media"),s));}return result;}
 @Override public void download(String blob,File target,JSONObject record)throws Exception {
  HttpsURLConnection c=connection(API+"files/"+id(blob)+"?alt=media","GET");MessageDigest hash=MessageDigest.getInstance("SHA-256");long size=0;
  try{success(c);try(InputStream in=c.getInputStream();OutputStream out=new FileOutputStream(target)){byte[] b=new byte[65536];for(int n;(n=in.read(b))!=-1;){size+=n;if(size>record.getLong("bytes"))throw new IOException("File Drive troppo grande");hash.update(b,0,n);out.write(b,0,n);}}if(size!=record.getLong("bytes")||!hex(hash.digest()).equals(record.getString("sha256")))throw new IOException("File Drive non integro; copia precedente conservata");}finally{c.disconnect();}
 }
 private static String hex(byte[] b){StringBuilder s=new StringBuilder();for(byte v:b)s.append(String.format(java.util.Locale.ROOT,"%02x",v&255));return s.toString();}
 private boolean verify(String blob,JSONObject record)throws Exception {HttpsURLConnection c=connection(API+"files/"+id(blob)+"?alt=media","GET");try{success(c);MessageDigest h=MessageDigest.getInstance("SHA-256");long size=0;try(InputStream in=c.getInputStream()){byte[] b=new byte[65536];for(int n;(n=in.read(b))!=-1;){size+=n;if(size>record.getLong("bytes"))return false;h.update(b,0,n);}}return size==record.getLong("bytes")&&hex(h.digest()).equals(record.getString("sha256"));}finally{c.disconnect();}}
 @Override public String blob(File source,JSONObject r)throws Exception {String hash=r.getString("sha256");if(!hash.matches("[a-f0-9]{64}"))throw new IOException("Impronta non valida");if(blobIndex==null){blobIndex=new java.util.HashMap<>();JSONArray all=list("appProperties has { key='kind' and value='officina-blob-1' }");for(int i=0;i<all.length();i++){JSONObject f=all.getJSONObject(i);String sha=f.optString("sha256Checksum","");if(!sha.isEmpty()&&sha.equals(f.getJSONObject("appProperties").optString("sha256")))blobIndex.put(sha+":"+f.getLong("size"),id(f.getString("id")));}}String key=hash+":"+r.getLong("bytes");if(blobIndex.containsKey(key))return blobIndex.get(key);String blob=upload(source,r,new JSONObject().put("kind","officina-blob-1").put("sha256",hash));blobIndex.put(key,blob);return blob;}
 @Override public String upload(File source,JSONObject r,JSONObject properties)throws Exception {
  long bytes=r.getLong("bytes");if(bytes<0||bytes>MobileStore.FILE_LIMIT)throw new IOException("File oltre il limite Drive");
  HttpsURLConnection init=connection("https://www.googleapis.com/upload/drive/v3/files?uploadType=resumable&fields=id,size,sha256Checksum","POST");String location;
  try{byte[] metadata=new JSONObject().put("name",properties.getString("kind")+"-"+r.getString("sha256")).put("mimeType","application/octet-stream").put("parents",new JSONArray().put("appDataFolder")).put("appProperties",properties).toString().getBytes(StandardCharsets.UTF_8);init.setDoOutput(true);init.setRequestProperty("Content-Type","application/json");init.setRequestProperty("X-Upload-Content-Type","application/octet-stream");init.setRequestProperty("X-Upload-Content-Length",String.valueOf(bytes));init.setFixedLengthStreamingMode(metadata.length);try(OutputStream out=init.getOutputStream()){out.write(metadata);}success(init);location=init.getHeaderField("Location");if(location==null)throw new IOException("Caricamento Drive non aperto");allowed(location);}finally{init.disconnect();}
  long offset=0;JSONObject done=null;
  try(InputStream in=new FileInputStream(source)){do{int length=(int)Math.min(8L*1024*1024,bytes-offset);byte[] buffer=new byte[length];int got=0;while(got<length){int n=in.read(buffer,got,length-got);if(n<0)throw new IOException("File locale cambiato durante il caricamento");got+=n;}
   HttpsURLConnection c=connection(location,"PUT");try{c.setDoOutput(true);c.setRequestProperty("Content-Type","application/octet-stream");c.setRequestProperty("Content-Range",bytes==0?"bytes */0":"bytes "+offset+"-"+(offset+length-1)+"/"+bytes);c.setFixedLengthStreamingMode(length);try(OutputStream out=c.getOutputStream()){out.write(buffer);}success(c);if(c.getResponseCode()==308){if(!("bytes=0-"+(offset+length-1)).equals(c.getHeaderField("Range")))throw new IOException("Caricamento parziale: riprova la sincronizzazione");}else{done=body(c);if(offset+length!=bytes)throw new IOException("Caricamento terminato prima del previsto");}}finally{c.disconnect();}offset+=length;
  }while(offset<bytes);}
  if(done==null||done.getLong("size")!=bytes)throw new IOException("Dimensione ricevuta da Drive non corretta");String file=id(done.getString("id"));if(!r.getString("sha256").equals(done.optString("sha256Checksum"))&&!verify(file,r))throw new IOException("File ricevuto da Drive non integro");return file;
 }
}
